import { parseFormula } from './parser.js'
import { parseAddr, addrName } from './addr.js'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ k: 'n', v })
const err = (v) => ({ k: 'e', v })
const ZERO = num(0)

function hasMisplaced(n, top) {
  if (!n) return false
  switch (n.t) {
    case 'range': return !top
    case 'bin': return hasMisplaced(n.l) || hasMisplaced(n.r)
    case 'un': case 'paren': return hasMisplaced(n.e)
    case 'call': return n.args.some((a) => hasMisplaced(a, true))
  }
  return false
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }
  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const cell = this.cells.get(key)
    if (!cell) return ZERO
    if (this.busy.has(key)) return err('#CYCLE!')
    this.busy.add(key)
    const v = this.compute(cell.content)
    this.busy.delete(key)
    this.memo.set(key, v)
    return v
  }
  compute(c) {
    if (c[0] === '=') {
      const ast = parseFormula(c.slice(1))
      if (!ast || hasMisplaced(ast, false)) return err('#ERR!')
      return this.ev(ast)
    }
    if (c === '') return ZERO
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
    if (ERRS.includes(c)) return err(c)
    return { k: 's', v: c }
  }
  format(v) {
    switch (v.k) {
      case 'n': return String(Number(v.v.toPrecision(10)))
      case 'b': return v.v ? 'TRUE' : 'FALSE'
      default: return v.v
    }
  }
  toNum(v) {
    if (v.k === 'n') return v
    if (v.k === 'b') return num(v.v ? 1 : 0)
    if (v.k === 's') return err('#VALUE!')
    return v
  }
  fin(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }
  rangeVals(n) {
    const p = parseAddr(n.a), q = parseAddr(n.b)
    if (!p || !q) return [err('#REF!')]
    const out = []
    for (let c = Math.min(p.c, q.c); c <= Math.max(p.c, q.c); c++)
      for (let r = Math.min(p.r, q.r); r <= Math.max(p.r, q.r); r++) out.push(this.get(addrName({ c, r })))
    return out
  }
  ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { k: 'b', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': {
        const a = parseAddr(n.name)
        return a ? this.get(addrName(a)) : err('#REF!')
      }
      case 'un': {
        const x = this.toNum(this.ev(n.e))
        if (x.k === 'e') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }
  bin(n) {
    const L = this.ev(n.l)
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      if (L.k === 'e') return L
      const R = this.ev(n.r)
      if (R.k === 'e') return R
      const c = this.compare(L, R)
      const r = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { k: 'b', v: r }
    }
    const l = this.toNum(L)
    if (l.k === 'e') return l
    const r = this.toNum(this.ev(n.r))
    if (r.k === 'e') return r
    switch (n.op) {
      case '+': return this.fin(l.v + r.v)
      case '-': return this.fin(l.v - r.v)
      case '*': return this.fin(l.v * r.v)
      case '/': return r.v === 0 ? err('#DIV/0!') : this.fin(l.v / r.v)
      case '^': return this.fin(Math.pow(l.v, r.v))
    }
  }
  compare(a, b) {
    const rank = { n: 0, s: 1, b: 2 }
    if (a.k !== b.k) return rank[a.k] - rank[b.k]
    const x = a.k === 'b' ? +a.v : a.v, y = b.k === 'b' ? +b.v : b.v
    if (a.k === 's') {
      const A = [...x], B = [...y]
      for (let i = 0; i < Math.min(A.length, B.length); i++) {
        const d = A[i].codePointAt(0) - B[i].codePointAt(0)
        if (d) return d
      }
      return A.length - B.length
    }
    return x < y ? -1 : x > y ? 1 : 0
  }
  call(n) {
    const name = n.name, args = n.args
    const agg = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (agg.includes(name)) {
      if (args.length < 1) return err('#ERR!')
      const vals = this.collectArgs(args)
      const e = vals.find((v) => v.k === 'e')
      if (e) return e
      if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
      const nums = []
      for (const v of vals) {
        const x = this.toNum(v)
        if (x.k === 'e') return x
        nums.push(x.v)
      }
      if (name === 'SUM') return this.fin(nums.reduce((a, b) => a + b, 0))
      if (name === 'AVG') return nums.length === 0 ? err('#DIV/0!') : this.fin(nums.reduce((a, b) => a + b, 0) / nums.length)
      if (name === 'MIN') return num(nums.reduce((a, b) => (b < a ? b : a)))
      return num(nums.reduce((a, b) => (b > a ? b : a)))
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const vals = this.collectArgs(args)
      if (vals.length !== 1) return vals.find((v) => v.k === 'e') || err('#ERR!')
      const x = this.toNum(vals[0])
      return x.k === 'e' ? x : num(Math.abs(x.v))
    }
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      if (args[0].t === 'range') return this.collectArgs([args[0]]).find((v) => v.k === 'e') || err('#ERR!')
      const c = this.ev(args[0])
      if (c.k === 'e') return c
      let t
      if (c.k === 'b') t = c.v
      else if (c.k === 'n') t = c.v !== 0
      else return err('#VALUE!')
      const br = args[t ? 1 : 2]
      if (br.t === 'range') return this.collectArgs([br]).find((v) => v.k === 'e') || err('#ERR!')
      return this.ev(br)
    }
    return err('#NAME?')
  }
  collectArgs(args) {
    const out = []
    for (const a of args) {
      if (a.t === 'range') out.push(...this.rangeVals(a))
      else out.push(this.ev(a))
    }
    return out
  }
}
EOF
