export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const r = Number(m[2])
  if (r < 1) return null
  const L = m[1].toUpperCase()
  const c = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + L.charCodeAt(1) - 64
  return { c, r }
}
export function addrName({ c, r }) {
  const L = c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
  return L + r
}
