function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ k: 'num', v: m[0] }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(s.slice(i)))) { toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

// Returns an AST, or null when the grammar rejects the body.
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const bad = new Error('syntax')
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw bad
    if (t.k === 'num') { p++; return { t: 'num', v: Number(t.v) } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw bad
      p++
      return { t: 'paren', e }
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { t: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw bad
        }
        return { t: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.k !== 'word') throw bad
        p++
        return { t: 'range', a: t.v, b: t2.v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { t: 'bool', v: true }
      if (u === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', name: t.v }
    }
    throw bad
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (err) {
    if (err === bad) return null
    throw err
  }
}
