      if (c.k === 'e') return c
      let t
      if (c.k === 'b') t = c.v
      else if (c.k === 'n') t = c.v !== 0
      else return err('#VALUE!')
      const br = args[t ? 1 : 2]
      if (br.t === 'range') return this.collectArgs([br]).find((v) => v.k === 'e') || err('#ERR!')
      return this.ev(br)
    }
    return err('#NAME?')
  }
  collectArgs(args) {
    const out = []
    for (const a of args) {
      if (a.t === 'range') out.push(...this.rangeVals(a))
      else out.push(this.ev(a))
    }
    return out
  }
}
